"""Real private API/etcd and Helm3: no node, pod execution, host config or external deployment."""
import base64,json,os,pathlib,subprocess
from private_api import Cluster
class HelmAPI:
 def __enter__(self):
  self.cluster=Cluster();self.root=self.cluster.root;self.namespace='helm-training'
  self.cluster.namespace(self.namespace)
  self.config=self.root/'helm-kubeconfig.json'
  cfg=dict(apiVersion='v1',kind='Config',clusters=[dict(name='private',cluster={'server':self.cluster.url,'certificate-authority':str(self.root/'ca.crt')})],users=[dict(name='private-admin',user={'client-certificate':str(self.root/'admin.crt'),'client-key':str(self.root/'admin.key')})],contexts=[dict(name='private',context={'cluster':'private','user':'private-admin','namespace':self.namespace})],**{'current-context':'private'})
  self.config.write_text(json.dumps(cfg));self.config.chmod(0o600)
  self.env={**os.environ,'GOMAXPROCS':'2','HELM_DRIVER':'secret','HELM_CACHE_HOME':str(self.root/'cache'),'HELM_CONFIG_HOME':str(self.root/'helm-config'),'HELM_DATA_HOME':str(self.root/'helm-data')}
  version=subprocess.check_output(['helm','version','--short'],env=self.env,text=True,timeout=4)
  if not version.startswith('v3.'):raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Helm3 required')
  print('NATIVE_HELM3_PRIVATE_API_AND_ETCD_READY',flush=True);return self
 def helm(self,*args):
  return subprocess.run(['helm',*map(str,args),'--kubeconfig',str(self.config),'--namespace',self.namespace],env=self.env,capture_output=True,text=True,timeout=20)
 def list(self,resource):
  code,body=self.cluster.request('GET','/api/v1/namespaces/'+self.namespace+'/'+resource);assert code==200
  return body['items']
 def __exit__(self,*args):self.cluster.close()
